//! Cross-check the AADL target model against a pinned vendor-derived reference.
//!
//! targets/*.aadl is authoritative for gale's hardware facts (the two-axes rework,
//! docs/architecture/three-modes-two-axes.md). A typed-in base address can still be
//! wrong, so every SoC device the model declares is compared with
//! targets/reference/<stem>.peripherals.tsv, generated by targets/reference/import.py
//! from a pinned, hash-checked stm32-data snapshot (derived from ST's CubeMX
//! database and SVD files).
//!
//! Rule: every device with a base below 0xE000_0000 (core peripherals such as the
//! MPU live in the Cortex-M PPB, which the SoC reference does not list) must exist
//! in the reference under its name, upper-cased or mapped by `ALIASES`, and at the
//! same base. Memories are not devices and are not checked here.

use crate::model::Target;
use std::collections::BTreeMap;

/// Where gale's device name differs from the reference's peripheral name.
/// Kept explicit so a rename on either side fails instead of silently matching.
const ALIASES: &[(&str, &str)] = &[("ADC", "ADC1")];

const PPB: u32 = 0xE000_0000;

/// Parse `name<TAB>0xBASE` rows; `#` lines are comments.
pub fn parse(tsv: &str) -> Result<BTreeMap<String, u32>, String> {
    let mut out = BTreeMap::new();
    for (i, line) in tsv.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (name, base) = line
            .split_once('\t')
            .ok_or_else(|| format!("reference line {}: expected `name<TAB>base`", i + 1))?;
        let hex = base.trim().trim_start_matches("0x");
        let v = u32::from_str_radix(hex, 16)
            .map_err(|_| format!("reference line {}: bad base `{base}`", i + 1))?;
        out.insert(name.trim().to_string(), v);
    }
    if out.is_empty() {
        return Err("reference has no rows -- the check would be vacuous".into());
    }
    Ok(out)
}

fn reference_name(device: &str) -> String {
    let up = device.to_ascii_uppercase();
    ALIASES
        .iter()
        .find(|(g, _)| *g == up)
        .map(|(_, r)| r.to_string())
        .unwrap_or(up)
}

/// Mismatches between the model and the reference; empty means they agree.
pub fn check(t: &Target, reference: &BTreeMap<String, u32>) -> Vec<String> {
    let mut bad = Vec::new();
    for d in &t.devices {
        if d.base >= PPB {
            continue;
        }
        let r = reference_name(&d.name);
        match reference.get(&r) {
            None => bad.push(format!(
                "{}: device `{}` (base 0x{:08X}) has no reference peripheral `{r}`",
                t.name, d.name, d.base
            )),
            Some(&b) if b != d.base => bad.push(format!(
                "{}: device `{}` base 0x{:08X} != reference {r} 0x{b:08X}",
                t.name, d.name, d.base
            )),
            Some(_) => {}
        }
    }
    bad
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Device, Region, Target};

    fn target(devs: &[(&str, u32)]) -> Target {
        Target {
            name: "T".into(),
            cpu: "c".into(),
            flash: Region { base: 0x0800_0000, len: 1 },
            sram: Region { base: 0x2000_0000, len: 1 },
            devices: devs
                .iter()
                .map(|(n, b)| Device { name: n.to_string(), base: *b, present: true, props: Default::default() })
                .collect(),
        }
    }

    fn reference() -> BTreeMap<String, u32> {
        parse("# c\nADC1\t0x40012400\nUSART1\t0x40013800\n").unwrap()
    }

    #[test]
    fn agreeing_model_passes() {
        assert!(check(&target(&[("Usart1", 0x4001_3800), ("Adc", 0x4001_2400)]), &reference()).is_empty());
    }

    #[test]
    fn wrong_base_fails() {
        assert_eq!(check(&target(&[("Usart1", 0x4001_3C00)]), &reference()).len(), 1);
    }

    #[test]
    fn unknown_device_fails() {
        assert_eq!(check(&target(&[("Uart9", 0x4000_0000)]), &reference()).len(), 1);
    }

    #[test]
    fn core_peripheral_is_out_of_scope() {
        assert!(check(&target(&[("Mpu", 0xE000_ED90)]), &reference()).is_empty());
    }

    #[test]
    fn empty_reference_refused() {
        assert!(parse("# only comments\n").is_err());
    }

    #[test]
    fn committed_references_agree_with_the_committed_model() {
        // The real check, on the committed spar items fixture and reference tables.
        let json = include_str!("../tests/golden/f100.items.json");
        for (board, stem) in [
            ("STM32F100::Board.vldiscovery", "stm32f100"),
            ("STM32G474::Board.nucleo", "stm32g474"),
            ("STM32WL55::Board.nucleo", "stm32wl55"),
            ("STM32WB55::Board.nucleo", "stm32wb55"),
            ("STM32G031::Board.nucleo", "stm32g031"),
        ] {
            let t = crate::model::parse_items(json, board);
            let tsv = std::fs::read_to_string(format!(
                "{}/../../targets/reference/{stem}.peripherals.tsv",
                env!("CARGO_MANIFEST_DIR")
            ))
            .unwrap();
            let bad = check(&t, &parse(&tsv).unwrap());
            assert!(bad.is_empty(), "{bad:?}");
        }
    }
}
